/* Learning Card (About, Contact, Privacy pages) */
.learning-card{background:var(--white);border-radius:var(--r-lg);padding:clamp(20px,3vw,32px) clamp(16px,2.5vw,26px);box-shadow:var(--shadow-sm);border:2px solid rgba(26,26,46,0.05);transition:var(--transition)}
.learning-card:hover{box-shadow:var(--shadow);border-color:rgba(255,107,107,0.15)}
.learning-card h3{font-family:var(--font-display);font-size:clamp(1.1rem,2.5vw,1.35rem);font-weight:800;color:var(--dark);margin-bottom:10px}
.learning-card p{font-family:var(--font-body);font-size:clamp(0.9rem,1.8vw,1rem);color:var(--gray);line-height:1.7}
.learning-card .card-icon{font-size:2.2rem;margin-bottom:8px}
.learning-card .card-title{font-size:clamp(0.95rem,1.8vw,1.05rem);margin-bottom:2px}
.learning-card .card-subtitle{font-size:clamp(0.72rem,1.2vw,0.82rem)}
/* About & privacy page layout tweaks */
#about-page .topic-grid,#contact-page .topic-grid{grid-template-columns:repeat(auto-fill,minmax(140px,1fr))}
