    BEDTIME MODE
 ══════════════════════════════════ */
body.bedtime-mode{
  --dark:#E2E8F0;--dark-2:#CBD5E1;--gray:#94A3B8;--light:#1E293B;--light-2:#162032;--white:#0F172A;
  --shadow-xs:0 1px 4px rgba(0,0,0,0.4);--shadow-sm:0 2px 12px rgba(0,0,0,0.5);--shadow:0 4px 24px rgba(0,0,0,0.6);
  background:#0F172A;color:#E2E8F0
}
