body.bedtime-mode .wave-bottom{background:url("data:image/svg+xml,%3Csvg viewBox='0 0 1200 120' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0,60 C200,10 500,110 800,60 C1000,25 1100,100 1200,70 L1200,120 L0,120 Z' fill='%231E293B'/%3E%3C/svg%3E") no-repeat top center/100% 70px}
body.bedtime-mode .quiz-score{color:#fff;background:#1E293B}
body,#secHeader,.blog-post-card,.video-card,.animal-card,.trust-card{transition:background-color 0.5s,color 0.5s,border-color 0.5s,box-shadow 0.3s,transform 0.3s}

