@media(min-width:769px){#secBottomNav{display:none!important}}
.no-results{text-align:center;padding:20px;color:var(--gray);grid-column:1/-1}

body.script:
//
// ============================================================
// POGO TUNES — Kids Learning Platform JavaScript
// ============================================================

// ---------- Gamification System ----------
const GAMIFICATION_KEY = 'pogotunes_gamification';

function getGamification() {
  try {
    const data = localStorage.getItem(GAMIFICATION_KEY);
    if (data) return JSON.parse(data);
  } catch (e) {}
  return { stars: 0, xp: 0, level: 1, badges: [], streak: 0, lastVisit: '' };
}

function saveGamification(g) {
  try { localStorage.setItem(GAMIFICATION_KEY, JSON.stringify(g)); } catch (e) {}
}

const LEVEL_THRESHOLDS = [0, 100, 250, 500, 800, 1200, 1700, 2300, 3000, 4000];
const BADGE_DEFS = [
  { id: 'first_star', name: 'First Star', icon: '⭐', desc: 'Collect your first star', xp: 10 },
  { id: 'super_star', name: 'Super Star', icon: '🌟', desc: 'Collect 10 stars', xp: 100 },
  { id: 'rocket', name: 'Rocket Learner', icon: '🚀', desc: 'Reach level 3', xp: 200 },
  { id: 'genius', name: 'Little Genius', icon: '🧠', desc: 'Reach level 5', xp: 500 },
  { id: 'streak_3', name: 'Dedicated', icon: '🔥', desc: '3-day streak', xp: 150 },
  { id: 'streak_7', name: 'Champion', icon: '🏆', desc: '7-day streak', xp: 500 },
  { id: 'explorer', name: 'Explorer', icon: '🗺️', desc: 'Visit 5 different pages', xp: 50 },
  { id: 'quiz_master', name: 'Quiz Master', icon: '📝', desc: 'Score 100% on a quiz', xp: 300 },
  { id: 'color_artist', name: 'Color Artist', icon: '🎨', desc: 'Complete a coloring page', xp: 100 },
  { id: 'memory_whiz', name: 'Memory Whiz', icon: '🃏', desc: 'Match all cards in under 30s', xp: 250 }
];

function addStars(count) {
  const g = getGamification();
  g.stars += count;
  g.xp += count * 10;
  checkLevelUp(g);
  checkBadges(g);
  saveGamification(g);
  updateUI(g);
  if (count > 0) triggerConfetti(50);
  return g;
}

function addXP(amount) {
  const g = getGamification();
  g.xp += amount;
  checkLevelUp(g);
  checkBadges(g);
  saveGamification(g);
  updateUI(g);
  return g;
}

function checkLevelUp(g) {
  let newLevel = 1;
  for (let i = LEVEL_THRESHOLDS.length - 1; i >= 0; i--) {
    if (g.xp >= LEVEL_THRESHOLDS[i]) { newLevel = i + 1; break; }
  }
  if (newLevel > g.level) {
    g.level = newLevel;
    triggerConfetti(150);
    showLevelUpToast(newLevel);
  }
}

function checkBadges(g) {
  const has = id => g.badges.some(b => b.id === id);
  if (g.stars >= 1 && !has('first_star')) awardBadge(g, 'first_star');
  if (g.stars >= 10 && !has('super_star')) awardBadge(g, 'super_star');
  if (g.level >= 3 && !has('rocket')) awardBadge(g, 'rocket');
  if (g.level >= 5 && !has('genius')) awardBadge(g, 'genius');
  const now = new Date().toDateString();
  if (g.lastVisit !== now) {
    const yesterday = new Date(Date.now() - 86400000).toDateString();
    g.streak = g.lastVisit === yesterday ? g.streak + 1 : 1;
    g.lastVisit = now;
    if (g.streak >= 3 && !has('streak_3')) awardBadge(g, 'streak_3');
    if (g.streak >= 7 && !has('streak_7')) awardBadge(g, 'streak_7');
  }
  const pages = JSON.parse(sessionStorage.getItem('pogotunes_visited') || '[]');
  if (pages.length >= 5 && !has('explorer')) awardBadge(g, 'explorer');
}

function awardBadge(g, badgeId) {
  const def = BADGE_DEFS.find(b => b.id === badgeId);
  if (!def) return;
  g.badges.push({ id: badgeId, name: def.name, icon: def.icon, desc: def.desc, earned: new Date().toISOString() });
  g.xp += def.xp;
  showBadgeToast(def);
}

function updateUI(g) {
  var starsEl = document.getElementById('headerStarsVal');
  if (starsEl) starsEl.textContent = g.stars;
  var streakEl = document.getElementById('headerStreakVal');
  if (streakEl) streakEl.textContent = g.streak;
}

function showLevelUpToast(level) {
  const popup = document.getElementById('kidsPopUp');
  if (!popup) return;
  popup.innerHTML = '<div class="toast level-up"><span class="toast-icon">🎉</span><div class="toast-text"><strong>Level Up!</strong><br>You reached Level ' + level + '!</div></div>';
  popup.classList.add('active');
  setTimeout(function() { popup.classList.remove('active'); }, 4000);
}

function showBadgeToast(badge) {
  const popup = document.getElementById('kidsPopUp');
  if (!popup) return;
  popup.innerHTML = '<div class="toast badge-earned"><span class="toast-icon">' + badge.icon + '</span><div class="toast-text"><strong>Badge Earned!</strong><br>' + badge.name + ' — ' + badge.desc + '</div></div>';
  popup.classList.add('active');
  setTimeout(function() { popup.classList.remove('active'); }, 5000);
}

// ---------- Confetti / Canvas Animation ----------
function triggerConfetti(count) {
  const canvas = document.getElementById('kidsConfetti');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
  const pieces = [];
  const colors = ['#FFD93D','#FF6B6B','#6BCBFF','#B28DFF','#6EE7B7','#FF9FF3','#FECA57','#48DBFB'];
  for (let i = 0; i < count; i++) {
    pieces.push({
      x: Math.random() * canvas.width,
      y: -20 - Math.random() * 100,
      w: 6 + Math.random() * 8,
      h: 4 + Math.random() * 6,
      color: colors[Math.floor(Math.random() * colors.length)],
      vx: (Math.random() - 0.5) * 4,
      vy: 2 + Math.random() * 4,
      rot: Math.random() * 360,
      rotSpeed: (Math.random() - 0.5) * 10,
      opacity: 1
    });
  }
  let frames = 0;
  function animate() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    let active = false;
    pieces.forEach(p => {
      if (p.opacity <= 0) return;
      active = true;
      p.x += p.vx;
      p.vy += 0.05;
      p.y += p.vy;
      p.rot += p.rotSpeed;
      if (p.y > canvas.height - 20) p.vy *= -0.6;
      if (frames > 80) p.opacity -= 0.015;
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate(p.rot * Math.PI / 180);
      ctx.globalAlpha = Math.max(0, p.opacity);
      ctx.fillStyle = p.color;
      ctx.fillRect(-p.w / 2, -p.h / 2, p.w, p.h);
      ctx.restore();
    });
    frames++;
    if (active && frames < 200) requestAnimationFrame(animate);
    else ctx.clearRect(0, 0, canvas.width, canvas.height);
  }
  animate();
}

// ---------- Search Overlay ----------
function openSearch() {
  const el = document.getElementById('secSearch');
  if (el) { el.classList.add('active'); document.getElementById('secSearch').querySelector('input').focus(); }
}

function closeSearch() {
  const el = document.getElementById('secSearch');
  if (el) el.classList.remove('active');
}

document.addEventListener('DOMContentLoaded', function() {
  const searchClose = document.querySelector('.search-overlay-close');
  if (searchClose) searchClose.addEventListener('click', closeSearch);
  document.querySelectorAll('.tag-chips span').forEach(function(el) {
    el.addEventListener('click', function() {
      const q = this.getAttribute('data-search');
      if (q) window.location.href = '/search?q=' + encodeURIComponent(q);
    });
  });
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') closeSearch();
  });
  // Category card smooth-scroll navigation
  document.querySelectorAll('.category-card').forEach(function(card) {
    card.addEventListener('click', function() {
      var name = this.querySelector('.cat-name');
      if (!name) return;
      var text = name.textContent.trim();
      var map = {'ABCs':'secABC','123s':'secCounting','Colors':'secColors','Animals':'secAnimals','Hindi':'secHindi','Songs':'secVideos'};
      var id = map[text];
      if (id) {
        var target = document.getElementById(id);
        if (target) target.scrollIntoView({behavior:'smooth'});
      }
    });
  });
  // Global delegation: interactive elements with data-text or data-sound
  document.addEventListener('click', function(e) {
    var target = e.target.closest('[data-text],[data-sound],[data-word],.abc-letter,.hindi-char,.count-num,.color-swatch,.animal-card,.bird-item,.fruit-item,.veg-item,.shape-item,.vehicle-item,.body-part-item,.phonics-item,.opposite-item,.day-item,.month-item,.habit-item,.helper-item');
    if (!target) return;
    if (target.closest('.category-card,.game-tab-btn,.quiz-choice,.dd-item,.dd-target,.memory-card,.short-card,.header-search-btn,.header-sound-btn,.header-bedtime-btn,.header-menu-btn,.search-overlay-close,.modal-close,.shorts-nav-btn,.subscribe-btn,.tag-chips span')) return;
    var dataText = target.getAttribute('data-text');
    var dataWord = target.getAttribute('data-word');
    var dataSound = target.getAttribute('data-sound');
    var dataAnimal = target.getAttribute('data-animal');
    var hasClass = target.classList.contains('abc-letter') || target.classList.contains('hindi-char') || target.classList.contains('count-num') || target.classList.contains('color-swatch') || target.classList.contains('animal-card') || target.classList.contains('bird-item') || target.classList.contains('fruit-item') || target.classList.contains('veg-item') || target.classList.contains('shape-item') || target.classList.contains('vehicle-item') || target.classList.contains('body-part-item') || target.classList.contains('phonics-item') || target.classList.contains('opposite-item') || target.classList.contains('day-item') || target.classList.contains('month-item') || target.classList.contains('habit-item') || target.classList.contains('helper-item');
    if (!hasClass && !dataText && !dataWord && !dataSound) return;
    var visualFeedback = target;
    var starCount = 1;
    if (dataSound === 'animal' && dataAnimal) {
      starCount = 2;
      playAnimalSound(dataAnimal);
      if (dataText) speakWord(dataText);
    } else if (dataSound === 'chime') {
      playSynthChime();
    } else if (dataWord && dataText) {
      speakWord(dataText + '. ' + dataWord);
    } else if (dataText) {
      speakWord(dataText);
    } else {
      var textContent = target.textContent.trim();
      var textMatch = textContent.match(/[A-Za-z0-9\u0900-\u097F]+/);
      var cleanText = textMatch ? textMatch[0] : textContent.slice(0,30);
      if (cleanText.length > 0) speakWord(cleanText);
      else return;
    }
    addStars(starCount);
    visualFeedback.style.transform = 'scale(1.25)';
    setTimeout(function() { visualFeedback.style.transform = ''; }, 300);
  });
});

// ---------- Shorts Modal ----------
var shortsList = [];
var currentShortIndex = 0;

function openShorts(videos) {
  shortsList = videos || [];
  currentShortIndex = 0;
  var modal = document.getElementById('shortsModal');
  if (modal) modal.classList.add('active');
  document.body.style.overflow = 'hidden';
  loadShort(0);
}

function closeShorts() {
  var modal = document.getElementById('shortsModal');
  if (modal) modal.classList.remove('active');
  document.body.style.overflow = '';
  var player = document.getElementById('shortsPlayer');
  if (player) player.innerHTML = '<div class="shorts-placeholder"><i class="fas fa-film"></i><p>Loading shorts...</p></div>';
}

function loadShort(index) {
  var player = document.getElementById('shortsPlayer');
  if (!player) return;
  if (!shortsList.length || index < 0 || index >= shortsList.length) {
    player.innerHTML = '<div class="shorts-placeholder"><i class="fas fa-film"></i><p>No more shorts.</p></div>';
    return;
  }
  currentShortIndex = index;
  var video = shortsList[index];
  player.innerHTML = '<div class="shorts-video-wrapper"><iframe src="https://www.youtube.com/embed/' + video.id + '?autoplay=1&mute=0&loop=1&playlist=' + video.id + '" frameborder="0" allow="autoplay; encrypted-media" allowfullscreen></iframe><div class="shorts-caption"><h4>' + video.title + '</h4></div></div>';
  var counter = document.getElementById('shortsCounter');
  if (counter) counter.textContent = (index + 1) + '/' + shortsList.length;
}

function nextShort() {
  if (currentShortIndex < shortsList.length - 1) loadShort(currentShortIndex + 1);
}

function prevShort() {
  if (currentShortIndex > 0) loadShort(currentShortIndex - 1);
}

document.addEventListener('DOMContentLoaded', function() {
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') closeShorts();
  });
});

