// ---------- Speech Audio Engine ----------
var pogoVoice = null;
function loadPogoVoice() {
  if (!('speechSynthesis' in window)) return;
  var voices = window.speechSynthesis.getVoices();
  if (!voices || !voices.length) return;
  pogoVoice = voices.find(function(v){ return /en[-_]?(US|GB|IN)/i.test(v.lang) && /female|en-us|en-gb/i.test(v.name); })
    || voices.find(function(v){ return /^en/i.test(v.lang); })
    || voices[0];
}
if ('speechSynthesis' in window) {
  loadPogoVoice();
  window.speechSynthesis.onvoiceschanged = loadPogoVoice;
}
function speakWord(text) {
  if (!soundEnabled || !text) return;
  try {
    if (!('speechSynthesis' in window)) { playChime(); return; }
    window.speechSynthesis.cancel();
    var u = new SpeechSynthesisUtterance(text);
    u.rate = 0.85;
    u.pitch = 1.15;
    u.lang = 'en-US';
    if (pogoVoice) u.voice = pogoVoice;
    window.speechSynthesis.speak(u);
  } catch (e) { playChime(); }
}
var pogoAudioCtx = null;
function playChime() {
  if (!soundEnabled) return;
  try {
    if (!pogoAudioCtx) pogoAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
    var ctx = pogoAudioCtx;
    var osc = ctx.createOscillator();
    var gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(660, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(880, ctx.currentTime + 0.15);
    gain.gain.setValueAtTime(0.18, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.3);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start();
    osc.stop(ctx.currentTime + 0.3);
  } catch (e) {}
}

// ---------- Animal Sound Effects ----------
var ANIMAL_SOUNDS = {
  lion:'roar',tiger:'growl',elephant:'trumpet',monkey:'ooh ooh',dog:'woof woof',cat:'meow',
  cow:'moo',horse:'neigh',goat:'baa',sheep:'baa baa',rabbit:'squeak',bear:'growl',
  fox:'yip',wolf:'howl',deer:'bleat',zebra:'neigh',giraffe:'hum',panda:'squeak',
  camel:'grunt',kangaroo:'chortle',dolphin:'click',whale:'song',shark:'silent',
  octopus:'bloop',penguin:'honk',parrot:'squawk',owl:'hoot',peacock:'call',
  butterfly:'flutter',bee:'buzz'
};
function playAnimalSound(animal) {
  if (!soundEnabled) return;
  var sound = ANIMAL_SOUNDS[animal] || animal;
  speakWord('The ' + animal + ' says ' + sound);
}
// ---------- Musical Chime (playful variant) ----------
function playSynthChime() {
  if (!soundEnabled) return;
  try {
    if (!pogoAudioCtx) pogoAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
    var ctx = pogoAudioCtx;
    var notes = [523.25, 659.25, 783.99];
    notes.forEach(function(freq, i) {
      var osc = ctx.createOscillator();
      var gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, ctx.currentTime + i * 0.1);
      gain.gain.setValueAtTime(0.15, ctx.currentTime + i * 0.1);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + i * 0.1 + 0.35);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(ctx.currentTime + i * 0.1);
      osc.stop(ctx.currentTime + i * 0.1 + 0.35);
    });
  } catch(e) {}
}

// ---------- Copy Link ----------
function copyPageLink() {
  var url = window.location.href;
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(url).then(function() {
      showCopyToast();
    }).catch(function() {
      fallbackCopy(url);
    });
  } else {
    fallbackCopy(url);
  }
  return false;
}

function fallbackCopy(text) {
  var ta = document.createElement('textarea');
  ta.value = text;
  ta.style.position = 'fixed';
  ta.style.opacity = '0';
  document.body.appendChild(ta);
  ta.select();
  try { document.execCommand('copy'); showCopyToast(); } catch (e) {}
  document.body.removeChild(ta);
}

function showCopyToast() {
  var popup = document.getElementById('kidsPopUp');
  if (!popup) return;
  popup.innerHTML = '<div class="toast copy-link"><span class="toast-icon">🔗</span><div class="toast-text"><strong>Link copied!</strong><br>Page URL copied to clipboard.</div></div>';
  popup.classList.add('active');
  setTimeout(function() { popup.classList.remove('active'); }, 3000);
}

// ---------- Related Posts AJAX Loader ----------
function loadRelatedPosts(label, containerId, maxResults) {
  maxResults = maxResults || 4;
  var container = document.getElementById(containerId);
  if (!container) return;
  container.innerHTML = '<div class="related-loading"><i class="fas fa-spinner fa-spin"></i> Loading...</div>';
  var url = '/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json&max-results=' + maxResults + '&callback=handleRelatedPosts';
  window.handleRelatedPosts = function(json) {
    var html = '';
    if (json.feed && json.feed.entry) {
      var entries = json.feed.entry;
      for (var i = 0; i < entries.length; i++) {
        var entry = entries[i];
        var title = entry.title.$t;
        var link = '';
        var thumb = '';
        if (entry.link) {
          for (var j = 0; j < entry.link.length; j++) {
            if (entry.link[j].rel === 'alternate') { link = entry.link[j].href; break; }
          }
        }
        if (entry.media$thumbnail) thumb = entry.media$thumbnail.url;
        html += '<div class="related-post"><a href="' + link + '"><div class="related-thumb"><img src="' + (thumb || 'https://via.placeholder.com/120x90?text=No+Image') + '" alt="' + title + '"/></div><div class="related-title">' + title + '</div></a></div>';
      }
    }
    if (!html) html = '<p class="no-related">No related posts found.</p>';
    container.innerHTML = html;
  };
  var script = document.createElement('script');
  script.src = url;
  document.head.appendChild(script);
}

// ---------- Scroll to Top ----------
document.addEventListener('DOMContentLoaded', function() {
  var btn = document.getElementById('scrollTopBtn');
  if (!btn) return;
  window.addEventListener('scroll', function() {
    if (window.scrollY > 400) btn.classList.add('visible');
    else btn.classList.remove('visible');
  });
});

// ---------- Page Load Animations (Intersection Observer) ----------
document.addEventListener('DOMContentLoaded', function() {
  if ('IntersectionObserver' in window) {
    var observer = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add('fade-in-visible');
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.1, rootMargin: '0px 0px -50px 0px' });
    document.querySelectorAll('.fade-in, .card, .section-title, .video-card, .abc-grid > *').forEach(function(el) {
      el.classList.add('fade-in-init');
      observer.observe(el);
    });
  } else {
    document.querySelectorAll('.fade-in, .card, .section-title, .video-card, .abc-grid > *').forEach(function(el) {
      el.classList.add('fade-in-visible');
    });
  }
});


// ---------- Interactive Game: Drag & Drop Matching ----------
var dragDropState = { dragItem: null, pairs: [], matched: 0, total: 0, containerId: null };

function initDragDrop(containerId, pairs) {
  dragDropState.containerId = containerId;
  dragDropState.pairs = pairs;
  dragDropState.matched = 0;
  dragDropState.total = pairs.length;
  var container = document.getElementById(containerId);
  if (!container) return;
  container.innerHTML = '<div class="dd-items"></div><div class="dd-targets"></div>';
  var itemsDiv = container.querySelector('.dd-items');
  var targetsDiv = container.querySelector('.dd-targets');
  var shuffled = pairs.slice().sort(function() { return Math.random() - 0.5; });
  shuffled.forEach(function(pair, idx) {
    var item = document.createElement('div');
    item.className = 'dd-item';
    item.textContent = pair.label;
    item.draggable = true;
    item.dataset.pairId = pair.id;
    item.dataset.index = idx;
    item.addEventListener('dragstart', function(e) {
      dragDropState.dragItem = this;
      this.classList.add('dragging');
      e.dataTransfer.effectAllowed = 'move';
    });
    item.addEventListener('dragend', function() {
      this.classList.remove('dragging');
      dragDropState.dragItem = null;
    });
    itemsDiv.appendChild(item);
  });
  shuffled.forEach(function(pair) {
    var target = document.createElement('div');
    target.className = 'dd-target';
    target.textContent = '?';
    target.dataset.pairId = pair.id;
    target.dataset.matchValue = pair.match;
    target.addEventListener('dragover', function(e) { e.preventDefault(); });
    target.addEventListener('dragenter', function(e) { e.preventDefault(); this.classList.add('drag-hover'); });
    target.addEventListener('dragleave', function() { this.classList.remove('drag-hover'); });
    target.addEventListener('drop', function(e) {
      e.preventDefault();
      this.classList.remove('drag-hover');
      var dragItem = dragDropState.dragItem;
      if (!dragItem || dragItem.dataset.pairId !== this.dataset.pairId) {
        if (dragItem) {
          dragItem.style.borderColor = 'var(--coral)';
          setTimeout(function() { dragItem.style.borderColor = ''; }, 500);
        }
        return;
      }
      if (this.classList.contains('matched')) return;
      this.textContent = this.dataset.matchValue;
      this.classList.add('matched');
      dragItem.classList.add('matched');
      dragItem.draggable = false;
      dragDropState.matched++;
      addStars(3);
      if (dragDropState.matched >= dragDropState.total) {
        showToast('🎉 Great job! You matched them all!', 3000);
        addStars(10);
      }
    });
    targetsDiv.appendChild(target);
  });
}

// ---------- Interactive Game: Memory Card Flip ----------
var memoryState = { cards: [], flipped: [], matched: 0, total: 0, locked: false, moves: 0, timer: null, seconds: 0, containerId: null, startTime: null };

function initMemoryGame(containerId, cardValues) {
  memoryState.containerId = containerId;
  memoryState.cards = [];
  memoryState.flipped = [];
  memoryState.matched = 0;
  memoryState.moves = 0;
  memoryState.seconds = 0;
  memoryState.locked = false;
  var container = document.getElementById(containerId);
  if (!container) return;
  var deck = cardValues.concat(cardValues).sort(function() { return Math.random() - 0.5; });
  memoryState.total = cardValues.length;
  container.innerHTML = '<div class="memory-info"><span>Moves: <strong id="memMoves">0</strong></span><span>Time: <strong id="memTime">0s</strong></span><span>Matched: <strong id="memMatched">0</strong>/' + memoryState.total + '</span></div><div class="memory-grid"></div>';
  var grid = container.querySelector('.memory-grid');
  deck.forEach(function(value, idx) {
    var card = document.createElement('div');
    card.className = 'memory-card';
    card.dataset.value = value;
    card.dataset.index = idx;
    card.innerHTML = '<div class="memory-card-inner"><div class="memory-card-front">' + value + '</div><div class="memory-card-back">?</div></div>';
    card.addEventListener('click', function() { flipCard(this); });
    grid.appendChild(card);
    memoryState.cards.push({ el: card, value: value, matched: false });
  });
  memoryState.startTime = Date.now();
  if (memoryState.timer) clearInterval(memoryState.timer);
  memoryState.timer = setInterval(function() {
    memoryState.seconds = Math.floor((Date.now() - memoryState.startTime) / 1000);
    var el = document.getElementById('memTime');
    if (el) el.textContent = memoryState.seconds + 's';
  }, 1000);
}

function flipCard(card) {
  if (memoryState.locked) return;
  if (card.classList.contains('flipped') || card.classList.contains('matched')) return;
  card.classList.add('flipped');
  memoryState.flipped.push(card);
  if (memoryState.flipped.length === 2) {
    memoryState.locked = true;
    memoryState.moves++;
    var el = document.getElementById('memMoves');
    if (el) el.textContent = memoryState.moves;
    var card1 = memoryState.flipped[0];
    var card2 = memoryState.flipped[1];
    if (card1.dataset.value === card2.dataset.value) {
      card1.classList.add('matched');
      card2.classList.add('matched');
      memoryState.matched++;
      var mel = document.getElementById('memMatched');
      if (mel) mel.textContent = memoryState.matched;
      memoryState.flipped = [];
      memoryState.locked = false;
      addStars(2);
      if (memoryState.matched >= memoryState.total) {
        if (memoryState.timer) clearInterval(memoryState.timer);
        var finalTime = document.getElementById('memTime');
        var timeText = finalTime ? finalTime.textContent : '';
        showToast('🎉 You matched all in ' + memoryState.moves + ' moves and ' + timeText + '!', 4000);
        addStars(15);
        if (memoryState.seconds <= 30) addXP(250);
      }
    } else {
      setTimeout(function() {
        card1.classList.remove('flipped');
        card2.classList.remove('flipped');
        memoryState.flipped = [];
        memoryState.locked = false;
      }, 1000);
    }
  }
}

// ---------- Interactive Game: Quiz ----------
var quizState = { questions: [], current: 0, score: 0, total: 0, containerId: null, answered: false };

function initQuiz(containerId, questions) {
  quizState.containerId = containerId;
  quizState.questions = questions.sort(function() { return Math.random() - 0.5; }).slice(0, 10);
  quizState.current = 0;
  quizState.score = 0;
  quizState.total = quizState.questions.length;
  quizState.answered = false;
  renderQuizQuestion();
}

function renderQuizQuestion() {
  var container = document.getElementById(quizState.containerId);
  if (!container) return;
  if (quizState.current >= quizState.total) {
    var pct = Math.round((quizState.score / quizState.total) * 100);
    var msg = pct >= 80 ? 'Amazing!' : pct >= 50 ? 'Good job!' : 'Keep trying!';
    var emoji = pct >= 80 ? '🎉' : pct >= 50 ? '👍' : '💪';
    container.innerHTML = '<div class="quiz-result"><span class="quiz-result-icon">' + emoji + '</span><h3>Quiz Complete!</h3><p>You scored <strong>' + quizState.score + '/' + quizState.total + '</strong> (' + pct + '%)</p><p>' + msg + '</p><button class="btn-primary" onclick="initQuiz(\'' + quizState.containerId + '\', ' + JSON.stringify(quizState.questions) + ')">Play Again</button></div>';
    if (pct >= 80) { addStars(10); addXP(200); }
    else if (pct >= 50) { addStars(5); addXP(50); }
    if (pct === 100) addXP(300);
    return;
  }
  var q = quizState.questions[quizState.current];
  quizState.answered = false;
  var choices = q.choices || [];
  var html = '<div class="quiz-question"><div class="quiz-progress">Question ' + (quizState.current + 1) + ' of ' + quizState.total + '</div><div class="quiz-progress-bar"><div style="width:' + ((quizState.current / quizState.total) * 100) + '%"></div></div><h3>' + q.question + '</h3><div class="quiz-choices">';
  choices.forEach(function(c, idx) {
    html += '<div class="quiz-choice" data-index="' + idx + '" onclick="answerQuiz(this, ' + idx + ')"><span class="choice-letter">' + String.fromCharCode(65 + idx) + '</span><span class="choice-text">' + c + '</span></div>';
  });
  html += '</div><div class="quiz-feedback" id="quizFeedback"></div></div>';
  container.innerHTML = html;
}

function answerQuiz(el, idx) {
  if (quizState.answered) return;
  quizState.answered = true;
  var q = quizState.questions[quizState.current];
  var correct = idx === q.answer;
  var feedback = document.getElementById('quizFeedback');
  var choices = document.querySelectorAll('.quiz-choice');
  choices.forEach(function(c, i) {
    c.style.pointerEvents = 'none';
    if (i === q.answer) c.classList.add('correct');
    if (i === idx && !correct) c.classList.add('wrong');
  });
  if (correct) {
    quizState.score++;
    if (feedback) feedback.innerHTML = '<span class="feedback-correct">✅ Correct! ' + (q.explanation || '') + '</span>';
    addStars(2);
  } else {
    if (feedback) feedback.innerHTML = '<span class="feedback-wrong">❌ Not quite. ' + (q.explanation || 'The correct answer was: ' + q.choices[q.answer]) + '</span>';
  }
  setTimeout(function() {
    quizState.current++;
    renderQuizQuestion();
  }, 1500);
}

// ---------- Interactive Game: Tracing / Coloring ----------
function initColoring(containerId, preset) {
  var container = document.getElementById(containerId);
  if (!container) return;
  container.innerHTML = '<div class="coloring-app"><canvas class="coloring-canvas" id="coloringCanvas"></canvas><div class="coloring-tools"><div class="color-palette"></div><input type="range" class="brush-size" id="brushSize" min="2" max="30" value="8"/><button class="btn-secondary" onclick="clearColoring()"><i class="fas fa-eraser"></i> Clear</button></div></div>';
  var canvas = document.getElementById('coloringCanvas');
  if (!canvas) return;
  var ctx = canvas.getContext('2d');
  canvas.width = container.clientWidth || 600;
  canvas.height = 400;
  ctx.fillStyle = '#fff';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  if (preset) drawColoringPreset(ctx, preset, canvas.width, canvas.height);
  var drawing = false;
  var color = '#FF6B6B';
  var size = 8;
  var palette = ['#FF6B6B','#FFD93D','#6BCBFF','#6EE7B7','#B28DFF','#FF9FF3','#FECA57','#48DBFB','#FF8A5C','#A29BFE','#FD79A8','#636e72','#2D3436','#FFFFFF'];
  var paletteDiv = container.querySelector('.color-palette');
  palette.forEach(function(c) {
    var swatch = document.createElement('div');
    swatch.className = 'color-swatch' + (c === color ? ' active' : '');
    swatch.style.background = c;
    if (c === '#FFFFFF') swatch.style.border = '1px solid #ddd';
    swatch.addEventListener('click', function() {
      paletteDiv.querySelectorAll('.color-swatch').forEach(function(s) { s.classList.remove('active'); });
      this.classList.add('active');
      color = c;
    });
    paletteDiv.appendChild(swatch);
  });
  var sizeSlider = document.getElementById('brushSize');
  if (sizeSlider) sizeSlider.addEventListener('input', function() { size = parseInt(this.value); });
  function startDraw(e) {
    drawing = true;
    var rect = canvas.getBoundingClientRect();
    var x = (e.touches ? e.touches[0].clientX : e.clientX) - rect.left;
    var y = (e.touches ? e.touches[0].clientY : e.clientY) - rect.top;
    ctx.beginPath();
    ctx.arc(x, y, size / 2, 0, Math.PI * 2);
    ctx.fillStyle = color;
    ctx.fill();
  }
  function draw(e) {
    if (!drawing) return;
    e.preventDefault();
    var rect = canvas.getBoundingClientRect();
    var x = (e.touches ? e.touches[0].clientX : e.clientX) - rect.left;
    var y = (e.touches ? e.touches[0].clientY : e.clientY) - rect.top;
    ctx.lineWidth = size;
    ctx.lineCap = 'round';
    ctx.strokeStyle = color;
    ctx.lineTo(x, y);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(x, y, size / 2, 0, Math.PI * 2);
    ctx.fillStyle = color;
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(x, y);
  }
  function endDraw() { drawing = false; ctx.beginPath(); }
  canvas.addEventListener('mousedown', startDraw);
  canvas.addEventListener('mousemove', draw);
  canvas.addEventListener('mouseup', endDraw);
  canvas.addEventListener('mouseleave', endDraw);
  canvas.addEventListener('touchstart', startDraw, { passive: true });
  canvas.addEventListener('touchmove', draw, { passive: false });
  canvas.addEventListener('touchend', endDraw, { passive: true });
  window.clearColoring = function() {
    ctx.fillStyle = '#fff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    if (preset) drawColoringPreset(ctx, preset, canvas.width, canvas.height);
    addStars(1);
  };
}

function drawColoringPreset(ctx, preset, w, h) {
  ctx.strokeStyle = '#ccc';
  ctx.lineWidth = 3;
  ctx.setLineDash([8, 5]);
  if (preset === 'apple' || preset === 'fruit') {
    ctx.beginPath(); ctx.arc(w / 2, h / 2 + 10, 60, 0, Math.PI * 2); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(w / 2, h / 2 - 50); ctx.lineTo(w / 2, h / 2 - 80); ctx.stroke();
    ctx.beginPath(); ctx.arc(w / 2 + 5, h / 2 - 80, 8, 0, Math.PI * 2); ctx.stroke();
  } else if (preset === 'star') {
    var cx = w / 2, cy = h / 2, outer = 70, inner = 30, points = 5;
    ctx.beginPath();
    for (var i = 0; i < points * 2; i++) {
      var r = i % 2 === 0 ? outer : inner;
      var angle = (i * Math.PI) / points - Math.PI / 2;
      var x = cx + r * Math.cos(angle);
      var y = cy + r * Math.sin(angle);
      i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    }
    ctx.closePath(); ctx.stroke();
  } else if (preset === 'circle') {
    ctx.beginPath(); ctx.arc(w / 2, h / 2, 80, 0, Math.PI * 2); ctx.stroke();
    ctx.beginPath(); ctx.arc(w / 2, h / 2, 50, 0, Math.PI * 2); ctx.stroke();
    ctx.beginPath(); ctx.arc(w / 2, h / 2, 20, 0, Math.PI * 2); ctx.stroke();
  } else if (preset === 'house') {
    ctx.beginPath(); ctx.moveTo(w / 2, h / 2 - 80); ctx.lineTo(w / 2 - 80, h / 2); ctx.lineTo(w / 2 + 80, h / 2); ctx.closePath(); ctx.stroke();
    ctx.strokeRect(w / 2 - 60, h / 2, 120, 80);
    ctx.strokeRect(w / 2 - 20, h / 2 + 20, 40, 60);
  }
  ctx.setLineDash([]);
}

// ---------- Interactive Game: Tracing ----------
function initTracing(containerId) {
  var container = document.getElementById(containerId);
  if (!container) return;
  var board = container.querySelector('#tracingBoard');
  var canvas = container.querySelector('#tracingCanvas');
  var guide = container.querySelector('#tracingGuideLetter');
  if (!canvas || !guide) return;
  var ctx = canvas.getContext('2d');
  canvas.width = canvas.parentElement.clientWidth || 300;
  canvas.height = 300;
  var tracingLetters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  var tracingIdx = 0;
  var drawing = false;
  function drawGuide(letter) {
    guide.textContent = letter;
    ctx.fillStyle = '#f0f0f0';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ddd';
    ctx.font = 'bold 120px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(letter, canvas.width / 2, canvas.height / 2 + 10);
    ctx.strokeStyle = '#ccc';
    ctx.lineWidth = 2;
    ctx.setLineDash([10, 8]);
    ctx.strokeText(letter, canvas.width / 2, canvas.height / 2 + 10);
    ctx.setLineDash([]);
  }
  function getPos(e) {
    var rect = canvas.getBoundingClientRect();
    return { x: (e.touches ? e.touches[0].clientX : e.clientX) - rect.left, y: (e.touches ? e.touches[0].clientY : e.clientY) - rect.top };
  }
  function startDraw(e) { e.preventDefault(); drawing = true; var p = getPos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); }
  function moveDraw(e) { if (!drawing) return; e.preventDefault(); var p = getPos(e); ctx.lineWidth = 8; ctx.lineCap = 'round'; ctx.strokeStyle = '#FF6B6B'; ctx.lineTo(p.x, p.y); ctx.stroke(); ctx.beginPath(); ctx.moveTo(p.x, p.y); }
  function endDraw() { drawing = false; ctx.beginPath(); }
  canvas.addEventListener('mousedown', startDraw);
  canvas.addEventListener('mousemove', moveDraw);
  canvas.addEventListener('mouseup', endDraw);
  canvas.addEventListener('mouseleave', endDraw);
  canvas.addEventListener('touchstart', startDraw, { passive: false });
  canvas.addEventListener('touchmove', moveDraw, { passive: false });
  canvas.addEventListener('touchend', endDraw);
  var clearBtn = container.querySelector('#tracingClearBtn');
  if (clearBtn) clearBtn.addEventListener('click', function() { drawGuide(tracingLetters[tracingIdx]); addStars(1); });
  var nextBtn = container.querySelector('#tracingNextBtn');
  if (nextBtn) nextBtn.addEventListener('click', function() {
    tracingIdx = (tracingIdx + 1) % tracingLetters.length;
    drawGuide(tracingLetters[tracingIdx]);
    addStars(2);
  });
  drawGuide(tracingLetters[0]);
}

// ---------- CMS Dynamic Widget Loader ----------
function initCMSWidgets() {
  document.querySelectorAll('.cms-dynamic-widget').forEach(function(widget) {
    var label = widget.getAttribute('data-label');
    var max = widget.getAttribute('data-max') || 6;
    var exclude = widget.getAttribute('data-exclude') || '';
    if (!label) return;
    var cb = 'cmscb' + Date.now() + Math.random().toString(36).substr(2, 5);
    window[cb] = function(json) {
      renderCMSWidget(widget, json, exclude);
      delete window[cb];
    };
    var url = '/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json&max-results=' + max + '&callback=' + cb + '&orderby=published';
    var s = document.createElement('script');
    s.src = url;
    document.head.appendChild(s);
  });
}

function renderCMSWidget(widget, json, exclude) {
  var entries = json.feed.entry || [];
  if (!entries.length) {
    widget.innerHTML = '<div class="no-results"><i class="fas fa-box-open"></i><p>Nothing here yet. Check back soon!</p></div>';
    return;
  }
  var isVideo = widget.classList.contains('videos-grid');
  var html = '';
  entries.forEach(function(entry) {
    var href = entry.link.filter(function(l) { return l.rel === 'alternate'; })[0].href;
    if (href === exclude) return;
    var title = entry.title.$t;
    var thumb = entry.media$thumbnail ? entry.media$thumbnail.url : '';
    if (isVideo) {
      html += '<div class="video-card"><a href="' + href + '"><div class="video-thumb" style="background:linear-gradient(135deg,#6BCBFF,#0984e3)">' + (thumb ? '<img src="' + thumb + '" alt="' + title + '" style="position:absolute;top:0;left:0;width:100%;height:100%;object-fit:cover"/>' : '') + '<span class="play-circle"><i class="fas fa-play"></i></span></div><div class="video-info"><h3>' + title + '</h3></div></a></div>';
    } else {
      html += '<div class="related-post-card"><a href="' + href + '">' + (thumb ? '<img src="' + thumb + '" alt="' + title + '"/>' : '<div class="related-placeholder"><i class="fas fa-file-alt"></i></div>') + '<span class="related-title">' + title + '</span></a></div>';
    }
  });
  widget.innerHTML = html || '<div class="no-results"><p>No more posts to show.</p></div>';
}

// ---------- Utility: Toast ----------
function showToast(msg, duration) {
  duration = duration || 3000;
  var popup = document.getElementById('kidsPopUp');
  if (!popup) return;
  popup.innerHTML = '<div class="toast generic-toast"><div class="toast-text">' + msg + '</div></div>';
  popup.classList.add('active');
  setTimeout(function() { popup.classList.remove('active'); }, duration);
}

// ---------- Init on DOM Ready ----------
document.addEventListener('DOMContentLoaded', function() {
  var g = getGamification();
  updateUI(g);
  checkBadges(g);
  saveGamification(g);
  var visited = JSON.parse(sessionStorage.getItem('pogotunes_visited') || '[]');
  var path = window.location.pathname;
  if (visited.indexOf(path) === -1) visited.push(path);
  sessionStorage.setItem('pogotunes_visited', JSON.stringify(visited));

  // Game tab switching
  document.querySelectorAll('.game-tab-btn').forEach(function(btn) {
    btn.addEventListener('click', function() {
      document.querySelectorAll('.game-tab-btn').forEach(function(b) { b.classList.remove('active'); });
      document.querySelectorAll('.game-panel').forEach(function(p) { p.classList.remove('active'); });
      this.classList.add('active');
      var target = document.getElementById(this.getAttribute('data-target'));
      if (target) target.classList.add('active');
    });
  });

  // Game start buttons
  var quizBtn = document.getElementById('quizStartBtn');
  if (quizBtn) quizBtn.addEventListener('click', function() {
    initQuiz('panelQuiz', [
      { question: 'Which letter comes after A?', choices: ['B','C','D','E'], answer: 0, explanation: 'B comes after A!' },
      { question: 'How many legs does a dog have?', choices: ['2','4','6','8'], answer: 1, explanation: 'A dog has 4 legs!' },
      { question: 'What color is the sky?', choices: ['Red','Green','Blue','Yellow'], answer: 2, explanation: 'The sky is blue!' },
      { question: 'Which is a fruit?', choices: ['Table','Apple','Chair','Book'], answer: 1, explanation: 'An apple is a fruit!' },
      { question: 'What does a cat say?', choices: ['Moo','Baa','Meow','Woof'], answer: 2, explanation: 'A cat says meow!' },
      { question: 'How many fingers on one hand?', choices: ['3','4','5','6'], answer: 2, explanation: 'You have 5 fingers!' },
      { question: 'Which shape has 3 sides?', choices: ['Circle','Square','Triangle','Star'], answer: 2, explanation: 'A triangle has 3 sides!' },
      { question: 'Which is a color?', choices: ['Monday','Purple','Table','Water'], answer: 1, explanation: 'Purple is a color!' },
      { question: 'What do bees make?', choices: ['Milk','Honey','Bread','Candy'], answer: 1, explanation: 'Bees make honey!' },
      { question: 'Which animal has a trunk?', choices: ['Cat','Dog','Elephant','Bird'], answer: 2, explanation: 'An elephant has a trunk!' },
      { question: 'What is 1 + 1?', choices: ['1','2','3','4'], answer: 1, explanation: '1 + 1 = 2!' },
      { question: 'Which is a vegetable?', choices: ['Carrot','Banana','Orange','Grape'], answer: 0, explanation: 'A carrot is a vegetable!' }
    ]);
  });

  var dragBtn = document.getElementById('dragStartBtn');
  if (dragBtn) dragBtn.addEventListener('click', function() {
    initDragDrop('panelDragDrop', [
      { id: 'dog', label: '🐕 Dog', match: 'Dog' },
      { id: 'cat', label: '🐈 Cat', match: 'Cat' },
      { id: 'elephant', label: '🐘 Elephant', match: 'Elephant' },
      { id: 'bird', label: '🐦 Bird', match: 'Bird' },
      { id: 'fish', label: '🐟 Fish', match: 'Fish' },
      { id: 'rabbit', label: '🐇 Rabbit', match: 'Rabbit' }
    ]);
  });

  var memBtn = document.getElementById('memoryStartBtn');
  if (memBtn) memBtn.addEventListener('click', function() {
    initMemoryGame('panelMemory', ['🐶','🐱','🐘','🐦','🐟','🐇','🐸','🐻']);
  });

  var tracingPanel = document.getElementById('panelTracing');
  if (tracingPanel) {
    var clearBtn = document.getElementById('tracingClearBtn');
    var nextBtn = document.getElementById('tracingNextBtn');
    if (clearBtn || nextBtn) initTracing('panelTracing');
  }

  // Short cards click handler
  document.querySelectorAll('.short-card').forEach(function(card) {
    card.addEventListener('click', function() {
      var vid = this.getAttribute('data-video-id');
      if (!vid) return;
      var label = this.querySelector('.short-label');
      var title = label ? label.textContent : 'Video';
      openShorts([{ id: vid, title: title }]);
    });
  });


  // Load CMS dynamic widgets (videos, related posts)
  initCMSWidgets();
});
